import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
for k in G: print(k, len(G[k]), len(G[k][0]))

def find_line(g):
    H,W=len(g),len(g[0])
    for r in range(H):
        if len(set(g[r]))==1 and g[r][0] not in (0,1):
            return ('h',r)
    for c in range(W):
        col=[g[r][c] for r in range(H)]
        if len(set(col))==1 and col[0] not in (0,1):
            return ('v',c)
def transform(grid):
    H,W=len(grid),len(grid[0])
    o='h' if True else 'v'
    orient,line=find_line(grid)
    lc=grid[line][0] if orient=='h' else grid[0][line]
    bg=0 if any(all(x==0 for x in r) for r in grid) else 1
    cells=[(r,c,grid[r][c]) for r in range(H) for c in range(W)
           if grid[r][c] not in (bg,lc) and ((orient=='h' and r!=line) or (orient=='v' and c!=line))]
    o=[r[:] for r in grid]
    for r,c,v in cells: o[r][c]=bg
    rs=[r for r,c,_ in cells]; cs=[c for _,c,_ in cells]
    if orient=='h':
        r0,r1=min(rs),max(rs); h=r1-r0+1
        if line<r0: nr=line+1; row8=nr+h
        else: nr=line-1-h+1; row8=nr-1
        for r,c,v in cells: o[nr+r-r0][c]=v
        for c in range(W): o[row8][c]=8
    else:
        c0,c1=min(cs),max(cs); w=c1-c0+1
        if line<c0: nc=line+1; col8=nc+w
        else: nc=line-1-w+1; col8=nc-1
        for r,c,v in cells: o[r][nc+c-c0]=v
        for r in range(H): o[r][col8]=8
    return o
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    ok=transform(G[k+' input'])==G[k+' output']
    print(k, ok)
    if not ok:
        a,b=transform(G[k+' input']),G[k+' output']
        for r in range(len(a)):
            if a[r]!=b[r]: print(r,a[r],b[r])

